contents.rollMessage:
%{
const actor = entity.entity ? entity.entity : entity;
const bonus = Number("${H0D_DEX_MOD + H0D_Initiative_Divers + H0D_DT_Bonus_Initiative_Total}$") || 0;
const roll = await (new foundry.dice.Roll("1d20 + (" + bonus + ")")).evaluate();
const natural = Number(roll.total || 0) - bonus;
let trackerStatus = "Combat Tracker non mis à jour";
try {
  let token = null;
  const controlled = canvas?.tokens?.controlled || [];
  token = controlled.find(t => t.actor === actor || t.document?.actorId === actor.id) || null;
  if (!token && typeof actor.getActiveTokens === "function") {
    const active = actor.getActiveTokens();
    token = active[0] || null;
  }
  const tokenDoc = token?.document || actor.token || null;
  if (!tokenDoc) throw new Error("Aucun token actif pour cet acteur.");
  let combat = game.combat || null;
  let combatant = combat?.combatants?.find(c => c.tokenId === tokenDoc.id) || null;
  if (!combatant) {
    const created = await foundry.documents.TokenDocument.createCombatants([tokenDoc], combat ? {combat} : {});
    combatant = created?.find(c => c.tokenId === tokenDoc.id) || created?.[0] || null;
    combat = combatant?.parent || game.combat || combat;
  }
  if (!combat || !combatant) throw new Error("Impossible de créer ou retrouver le combattant.");
  await combat.setInitiative(combatant.id, roll.total);
  trackerStatus = "Ajoutée au Combat Tracker";
} catch (err) {
  console.warn("H0D — initiative : Combat Tracker non mis à jour.", err);
}
return "<div class=\"h0d-chat-card h0d-chat-initiative h0d-chat-pj\">"
  + "<div class=\"h0d-chat-headline\">Initiative</div>"
  + "<table class=\"h0d-chat-summary\"><tr><td><strong>Résultat</strong></td><td><strong>" + roll.total + "</strong></td></tr></table>"
  + "<div class=\"h0d-chat-status\">" + trackerStatus + "</div>"
  + "<details><summary>Détails du jet</summary><table>"
  + "<tr><td>d20</td><td><strong>" + natural + "</strong></td></tr>"
  + "<tr><td>Bonus total</td><td><strong>" + (bonus >= 0 ? "+" : "") + bonus + "</strong></td></tr>"
  + "</table></details>"
  + "</div>";
}%

rowLayout.rollMessage:
${#?{H0D_Attaque_Mod_Situ:'Modificateur situationnel'[number]|0}}$
${#H0D_BBA_TMP:= H0D_BBA}$
${#H0D_CARAC_ATK_TMP:= switchCase(item.H0D_Arme_Categorie,'melee',H0D_FOR_MOD,'distance',H0D_DEX_MOD,'jet',switchCase(item.H0D_Arme_Carac_Attaque,'FOR',H0D_FOR_MOD,'DEX',H0D_DEX_MOD,0),'speciale',switchCase(item.H0D_Arme_Carac_Attaque,'FOR',H0D_FOR_MOD,'DEX',H0D_DEX_MOD,0),switchCase(item.H0D_Arme_Carac_Attaque,'FOR',H0D_FOR_MOD,'DEX',H0D_DEX_MOD,0))}$
${#H0D_SIZE_TMP:= H0D_Taille_Mod_Calc}$
${#H0D_ATK_TMP:= H0D_BBA + switchCase(item.H0D_Arme_Categorie,'melee',H0D_FOR_MOD,'distance',H0D_DEX_MOD,'jet',switchCase(item.H0D_Arme_Carac_Attaque,'FOR',H0D_FOR_MOD,'DEX',H0D_DEX_MOD,0),'speciale',switchCase(item.H0D_Arme_Carac_Attaque,'FOR',H0D_FOR_MOD,'DEX',H0D_DEX_MOD,0),switchCase(item.H0D_Arme_Carac_Attaque,'FOR',H0D_FOR_MOD,'DEX',H0D_DEX_MOD,0)) + H0D_Taille_Mod_Calc + item.H0D_Arme_Bonus_Attaque + item.H0D_Arme_Trait_Attaque_Total + H0D_EQ_Trait_Attaque_Global_Total + (item.H0D_Arme_Trait_Lourd_FOR_Min_Calc > H0D_FOR ? -2 : 0) + H0D_Encombrement_Malus_Calc + H0D_DT_Bonus_Attaque_Global_Total + switchCase(item.H0D_Arme_Categorie,'distance',H0D_DT_Bonus_Attaque_Distance_Total,'jet',H0D_DT_Bonus_Attaque_Distance_Total,'melee',H0D_DT_Bonus_Attaque_Melee_Total,0)}$
${#H0D_DMG_TMP:= switchCase(item.H0D_Arme_Carac_Degats,'FOR',H0D_FOR_MOD,'DEX',H0D_DEX_MOD,0) + item.H0D_Arme_Bonus_Degats + H0D_EQ_Trait_Degats_Global_Total + H0D_DT_Bonus_Degats_Global_Total + switchCase(item.H0D_Arme_Categorie,'distance',H0D_DT_Bonus_Degats_Distance_Total,'jet',H0D_DT_Bonus_Degats_Distance_Total,'melee',H0D_DT_Bonus_Degats_Melee_Total,0)}$
${#H0D_Jet_Arme:=[1d20]}$
%{
try {
  const actor = entity.entity ? entity.entity : entity;
  const weapon = linkedEntity;
  if (!weapon) return "<strong>Arme introuvable.</strong>";

  const wp = weapon.system && weapon.system.props ? weapon.system.props : {};
  const category = String(wp.H0D_Arme_Categorie || "");
const mode = category === "melee" ? "Aucune" : String(wp.H0D_Arme_Mode_Munition || "Aucune");
  const family = String(wp.H0D_Arme_Type_Munition || "");
  const cost = Math.max(1, Number(wp.H0D_Arme_Consommation_Munition || 1));
  const items = actor.items ? actor.items : entity.items;

  const cdDuration = Math.max(0, Number(wp.H0D_Arme_Trait_Cooldown_Total || 0));
  let cdState = weapon.getFlag("custom-system-builder", "h0dCooldown") || {};
  let cdMode = String(cdState.mode || "Auto");
  let cdActive = cdState.active === true;
  let cdElapsed = Math.max(0, Number(cdState.elapsed || 0));
  const cdCombat = game.combat || null;

  if (cdDuration > 0 && cdActive) {
    if (cdMode === "Auto") {
      const sameCombat = cdCombat
        && Number(cdCombat.round || 0) > 0
        && String(cdState.combatId || "") === String(cdCombat.id || "")
        && Number(cdState.startRound || 0) > 0;

      if (sameCombat) {
        cdElapsed = Math.max(0, Number(cdCombat.round || 0) - Number(cdState.startRound || 0));

        if (cdElapsed >= cdDuration) {
          cdActive = false;
          cdState = {...cdState, active:false, elapsed:cdDuration};
          await weapon.setFlag("custom-system-builder", "h0dCooldown", cdState);
        } else {
          if (cdElapsed !== Number(cdState.elapsed || 0)) {
            cdState = {...cdState, elapsed:cdElapsed};
            await weapon.setFlag("custom-system-builder", "h0dCooldown", cdState);
          }
          return "<strong>RECHARGE EN COURS — " + weapon.name + "</strong><br>"
            + "Mode : automatique (Combat Tracker)<br>"
            + "Rounds écoulés : " + cdElapsed + " / " + cdDuration + "<br>"
            + "Disponible au round " + (Number(cdState.startRound || 0) + cdDuration) + ".";
        }
      } else {
        cdActive = false;
        cdState = {mode:cdMode, active:false, elapsed:cdDuration, combatId:"", startRound:0};
        await weapon.setFlag("custom-system-builder", "h0dCooldown", cdState);
      }
    } else {
      if (cdElapsed < cdDuration) {
        return "<strong>RECHARGE EN COURS — " + weapon.name + "</strong><br>"
          + "Mode : manuel<br>"
          + "Rounds écoulés : " + cdElapsed + " / " + cdDuration + ".";
      }

      cdActive = false;
      cdState = {...cdState, active:false, elapsed:cdDuration};
      await weapon.setFlag("custom-system-builder", "h0dCooldown", cdState);
    }
  }


  function esc(v) {
    return String(v === undefined || v === null ? "" : v)
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#039;");
  }

const h0dTargets = Array.from(game.user?.targets || []);

  function h0dNum(v) {
    const n = Number(v);
    return Number.isFinite(n) ? n : 0;
  }
  function h0dBool(v) {
    return v === true || v === "true" || v === 1 || v === "1";
  }
  function h0dHas(o, k) {
    return !!o && Object.prototype.hasOwnProperty.call(o, k);
  }
  function h0dRows(v) {
    if (Array.isArray(v)) return v;
    if (v && typeof v === "object") return Object.values(v);
    return [];
  }
  function h0dTraitDef(ip, prefix) {
    const directKey = prefix + "_Trait_DEF_Total";
    if (h0dHas(ip, directKey) && ip[directKey] !== "") {
      const direct = Number(ip[directKey]);
      if (Number.isFinite(direct)) return direct;
    }
    let total = 0;
    for (const row of h0dRows(ip[prefix + "_Traits_Table"])) {
      if (!row || typeof row !== "object") continue;
      const activeKey = prefix + "_Trait_Actif";
      if (h0dHas(row, activeKey) && !h0dBool(row[activeKey])) continue;
      const effect = String(
        row[prefix + "_Trait_Effet_Actif_Calc"]
        ?? row[prefix + "_Trait_Effet"]
        ?? ""
      ).toUpperCase();
      if (effect !== "DEF") continue;
      total += h0dNum(
        row[prefix + "_Trait_Valeur_Active_Calc"]
        ?? row[prefix + "_Trait_Valeur"]
        ?? 0
      );
    }
    return total;
  }

  function h0dResolveDefense(targetActor) {
    if (!targetActor) return null;
    const p = targetActor.system?.props || {};
    const items = Array.from(targetActor.items || []);

    for (const key of [
      "H0D_Defense_Totale_Calc",
      "H0D_Defense_Totale",
      "H0D_Creature_DEF_Total_Calc",
      "H0D_Machine_DEF_Total_Calc"
    ]) {
      if (h0dHas(p, key) && p[key] !== "") {
        const v = Number(p[key]);
        if (Number.isFinite(v)) return v;
      }
    }

    if (h0dHas(p, "H0D_DEX") || h0dHas(p, "H0D_Classe_Fort_Rangs")) {
      const dexMod = Math.floor((h0dNum(p.H0D_DEX) - 10) / 2);
      const fort = h0dNum(p.H0D_Classe_Fort_Rangs);
      const rapide = h0dNum(p.H0D_Classe_Rapide_Rangs);
      const robuste = h0dNum(p.H0D_Classe_Robuste_Rangs);
      const intelligent = h0dNum(p.H0D_Classe_Intelligent_Rangs);
      const devoue = h0dNum(p.H0D_Classe_Devoue_Rangs);
      const charismatique = h0dNum(p.H0D_Classe_Charismatique_Rangs);
      const prog = r => (r > 0 ? 1 : 0) + (r > 1 ? 1 : 0) + (r > 3 ? 1 : 0) + (r > 6 ? 1 : 0) + (r > 8 ? 1 : 0);
      const classDefense =
        prog(fort)
        + (rapide > 0 ? 3 + Math.floor(rapide / 2) : 0)
        + prog(robuste)
        + Math.floor((intelligent + 1) / 3)
        + prog(devoue)
        + Math.floor((charismatique + 1) / 3);
      const sizeMap = {Infime:8,Minuscule:4,TresPetite:2,Petite:1,Moyenne:0,Grande:-1,TresGrande:-2,Gigantesque:-4,Colossale:-8};
      const sizeMod = sizeMap[String(p.H0D_Taille || "Moyenne")] ?? 0;
      let armorBase = 0, equipmentTraitDef = 0, featDef = 0;

      for (const item of items) {
        const ip = item.system?.props || {};
        const stockage = String(ip.H0D_Stockage || "");
        if (stockage === "PJ" && h0dHas(ip,"H0D_Armure_Active") && h0dBool(ip.H0D_Armure_Active)) {
          armorBase += h0dNum(ip.H0D_Armure_Bonus_Defense);
          equipmentTraitDef += h0dTraitDef(ip,"H0D_Armure");
        }
        if (stockage === "PJ" && String(ip.H0D_Objet_Type || "") !== "Munition" && h0dHas(ip,"H0D_Objet_Actif") && h0dBool(ip.H0D_Objet_Actif)) {
          equipmentTraitDef += h0dTraitDef(ip,"H0D_Objet");
        }
        if (h0dHas(ip,"H0D_DT_Actif") && h0dBool(ip.H0D_DT_Actif)) {
          featDef += h0dNum(ip.H0D_DT_Bonus_DEF_Perm) + h0dNum(ip.H0D_DT_Bonus_DEF_Esquive);
        }
      }
      return 10 + dexMod + classDefense + armorBase + sizeMod + h0dNum(p.H0D_Defense_Divers) + featDef + equipmentTraitDef;
    }

    if (h0dHas(p,"H0D_Creature_DEF_Base")) {
      let armorDef=0, objectDef=0, moduleDef=0;
      for (const item of items) {
        const ip=item.system?.props || {};
        const stockage=String(ip.H0D_Stockage || "");
        if (stockage === "PJ" && h0dHas(ip,"H0D_Armure_Active") && h0dBool(ip.H0D_Armure_Active)) {
          armorDef += h0dNum(ip.H0D_Armure_Bonus_Defense) + h0dTraitDef(ip,"H0D_Armure");
        }
        if (stockage === "PJ" && String(ip.H0D_Objet_Type || "") !== "Munition" && h0dHas(ip,"H0D_Objet_Actif") && h0dBool(ip.H0D_Objet_Actif)) {
          objectDef += h0dTraitDef(ip,"H0D_Objet");
        }
        if (h0dHas(ip,"H0D_CM_Actif") && h0dBool(ip.H0D_CM_Actif)) {
          moduleDef += h0dNum(ip.H0D_CM_Bonus_DEF);
        }
      }
      return Math.max(0,h0dNum(p.H0D_Creature_DEF_Base)+h0dNum(p.H0D_Creature_DEF_Divers)+armorDef+objectDef+moduleDef);
    }

    if (h0dHas(p,"H0D_Machine_DEF_Corps_Base")) {
      let pieceDef=0;
      for (const item of items) {
        const ip=item.system?.props || {};
        if (h0dHas(ip,"H0D_Composant_Bonus_DEF_Machine")) {
          const state=String(ip.H0D_Composant_Etat || "");
          if (h0dNum(ip.H0D_Composant_PV_Actuels)>0 && state!=="Detruit" && state!=="Detache") {
            pieceDef += h0dNum(ip.H0D_Composant_Bonus_DEF_Machine);
          }
        }
      }
      return Math.max(0,h0dNum(p.H0D_Machine_DEF_Corps_Base)+pieceDef+h0dNum(p.H0D_Machine_Mod_DEF_Temp));
    }
    return null;
  }

  function h0dAttackVerdict(natural,total,defense) {
    const n=Number(natural);
    const hasDefense = defense !== null && defense !== undefined && Number.isFinite(Number(defense));
    const def = hasDefense ? Number(defense) : null;
    const margin = hasDefense ? Number(total) - def : null;

    if (n === 1) return {hit:false,text:"RATÉ — 1 naturel",margin};
    if (n === 20) return {hit:true,text:"TOUCHÉ — 20 naturel",margin};
    if (!hasDefense) return {hit:null,text:"NON COMPARÉ",margin:null};

    const hit = Number(total) >= def;
    return {hit,margin,text:hit ? "TOUCHÉ" : "RATÉ"};
  }

  function compatibleAmmo() {
    return items.filter(function(i) {
      const p = i.system && i.system.props ? i.system.props : {};
      return String(p.H0D_Objet_Type || "") === "Munition"
        && String(p.H0D_Stockage || "PJ") === "PJ"
        && String(p.H0D_Objet_Munition_Famille || "") === family
        && Number(p.H0D_Objet_Quantite || 0) > 0;
    });
  }

  let ammoItem = null;
  let ammoName = "—";
  let ammoElement = "Aucun";
  let ammoAtk = 0;
  let ammoDmg = 0;
  let ammoArmor = 0;
  let ammoEffect = "";
  let afterAmmoText = "—";

  if (mode === "Direct") {
    const candidates = compatibleAmmo();
    ammoItem = candidates.find(function(i) {
      const p = i.system && i.system.props ? i.system.props : {};
      return p.H0D_Objet_Munition_Active === true || p.H0D_Objet_Munition_Active === "true";
    });

    if (!ammoItem && candidates.length === 1) ammoItem = candidates[0];

    if (!ammoItem) {
      const msg = candidates.length > 1
        ? weapon.name + " : plusieurs munitions " + family + " compatibles. Sélectionnez-en une dans MUNITIONS."
        : weapon.name + " : aucune munition " + family + " disponible.";
      if (ui.notifications) ui.notifications.warn(msg);
      return "<strong>TIR IMPOSSIBLE</strong><br>" + esc(msg);
    }

    const ap = ammoItem.system && ammoItem.system.props ? ammoItem.system.props : {};
    const stock = Math.max(0, Number(ap.H0D_Objet_Quantite || 0));

    if (stock < cost) {
      const msg = weapon.name + " : " + ammoItem.name + " insuffisante (" + stock + "/" + cost + ").";
      if (ui.notifications) ui.notifications.warn(msg);
      return "<strong>TIR IMPOSSIBLE</strong><br>" + esc(msg);
    }

    ammoName = ammoItem.name;
    ammoElement = String(ap.H0D_Objet_Munition_Element || "Aucun");
    ammoAtk = Number(ap.H0D_Objet_Munition_Bonus_Attaque || 0);
    ammoDmg = Number(ap.H0D_Objet_Munition_Bonus_Degats || 0);
    ammoArmor = Number(ap.H0D_Objet_Munition_Anti_Blindage || 0);
    ammoEffect = String(ap.H0D_Objet_Munition_Effet_Court || "");
    afterAmmoText = (stock - cost) + " en stock";
  }

  if (mode === "Chargeur") {
    const cur = Math.max(0, Number(wp.H0D_Arme_Munitions || 0));

    if (cur < cost) {
      const msg = weapon.name + " : chargeur insuffisant (" + cur + "/" + cost
        + "). Cliquez sur la colonne Munition pour recharger.";
      if (ui.notifications) ui.notifications.warn(msg);
      return "<strong>TIR IMPOSSIBLE</strong><br>" + esc(msg);
    }

    const loadedAmmo = weapon.getFlag("custom-system-builder", "h0dAmmoLoaded") || {};
    ammoName = String(loadedAmmo.name || "Munition chargée");
    ammoElement = String(loadedAmmo.element || "Aucun");
    ammoAtk = Number(loadedAmmo.attackBonus || 0);
    ammoDmg = Number(loadedAmmo.damageBonus || 0);
    ammoArmor = Number(loadedAmmo.antiArmor || 0);
    ammoEffect = String(loadedAmmo.effect || "");
    afterAmmoText = (cur - cost) + "/" + Math.max(0, Number(wp.H0D_Arme_Munitions_Max || 0))
      + " dans le chargeur";
  }

  const bbaMod = Number(localVars.H0D_BBA_TMP || 0);
  const abilityAttackMod = Number(localVars.H0D_CARAC_ATK_TMP || 0);
  const sizeAttackMod = Number(localVars.H0D_SIZE_TMP || 0);

  let rangePenalty = 0;
  let measuredDistance = null;
  let rangeIncrement = null;
  let rangeBand = null;
  let maxRangeBands = null;
  let rangeUnits = "";
  let targetName = "Aucune cible";
  let softWarning = "";
  if (h0dTargets.length === 1) {
    const t = h0dTargets[0];
    targetName = t.name || t.actor?.name || "Cible";
  } else if (h0dTargets.length > 1) {
    targetName = "Plusieurs cibles (" + h0dTargets.length + ")";
    softWarning = "Plusieurs cibles : DEF et portée non comparées ; jet effectué sans malus de portée.";
  }

  const isRangedAttack = category === "distance" || category === "jet";

  if (isRangedAttack) {
    const rawRange = String(wp.H0D_Arme_Portee || "0").replace(",", ".");
    const rangeMatch = rawRange.match(/-?\d+(?:\.\d+)?/);
    const baseRange = rangeMatch ? Number(rangeMatch[0]) : 0;
    const traitRange = Math.max(0, Number(wp.H0D_Arme_Trait_Portee_Total || 0));
    rangeIncrement = baseRange + traitRange;

    // Ciblage soft : l'absence de cible/token/canvas n'empêche pas le jet.
    // Dans ce cas, la portée n'est pas mesurée et aucun malus de portée n'est appliqué.
    if (h0dTargets.length !== 1) {
      if (!softWarning) {
        softWarning = "Aucune cible : DEF et portée non comparées ; jet effectué sans malus de portée.";
      }
      if (ui.notifications) ui.notifications.warn(softWarning);
    } else if (!(rangeIncrement > 0)) {
      softWarning = weapon.name + " : portée invalide ; jet effectué sans calcul de portée.";
      if (ui.notifications) ui.notifications.warn(softWarning);
    } else if (!canvas?.ready || !canvas.grid || !canvas.tokens) {
      softWarning = "Canvas indisponible : jet effectué sans calcul de portée.";
      if (ui.notifications) ui.notifications.warn(softWarning);
    } else {
      const shooters = (canvas.tokens.controlled || []).filter(function(t) {
        return t.actor === actor || t.document?.actorId === actor.id;
      });

      if (shooters.length !== 1) {
        softWarning = shooters.length === 0
          ? "Sélectionnez le token du tireur pour calculer la portée. Jet effectué sans calcul de portée."
          : "Un seul token du tireur doit être sélectionné pour calculer la portée. Jet effectué sans calcul de portée.";
        if (ui.notifications) ui.notifications.warn(softWarning);
      } else {
        const shooter = shooters[0];
        const target = h0dTargets[0];
        targetName = target.name || target.actor?.name || "Cible";

        const measurement = canvas.grid.measurePath([
          {x: shooter.center.x, y: shooter.center.y},
          {x: target.center.x, y: target.center.y}
        ]);

        measuredDistance = Number(measurement?.distance ?? 0);
        rangeUnits = String(canvas.dimensions?.units || canvas.scene?.grid?.units || "").trim();

        const epsilon = 1e-6;
        rangeBand = Math.max(1, Math.ceil((measuredDistance - epsilon) / rangeIncrement));
        maxRangeBands = category === "jet" ? 5 : 10;

        if (measuredDistance > (rangeIncrement * maxRangeBands) + epsilon) {
          const msg = weapon.name + " : cible hors portée maximale ("
            + measuredDistance.toFixed(1) + (rangeUnits ? " " + rangeUnits : "")
            + " / " + (rangeIncrement * maxRangeBands)
            + (rangeUnits ? " " + rangeUnits : "") + ").";
          if (ui.notifications) ui.notifications.warn(msg);
          return "<strong>CIBLE HORS PORTÉE</strong><br>" + esc(msg);
        }

        rangePenalty = -2 * Math.max(0, rangeBand - 1);
      }
    }
  }

  const attackMod = Number(localVars.H0D_ATK_TMP || 0);
  const damageFlat = Number(localVars.H0D_DMG_TMP || 0);
  const baseDamage = String(wp.H0D_Arme_Degats || "0").trim() || "0";

  let critThreshold = Number(wp.H0D_Arme_Critique_Seuil || 0);
  let critMult = Number(wp.H0D_Arme_Critique_Multiplicateur || 0);

  if (!(critThreshold >= 2 && critThreshold <= 20)) critThreshold = 20;
  if (!(critMult >= 2)) critMult = 2;

  critThreshold = Math.max(2, Math.min(20, critThreshold));
  critMult = Math.max(2, Math.min(5, critMult));
  const threatLabel = critThreshold + "–20/x" + critMult;

  const situationalMod = Number("${H0D_Attaque_Mod_Situ}$") || 0;
  const natural = Number(localVars.H0D_Jet_Arme || 0);
  const attackTotal = natural + attackMod + ammoAtk + rangePenalty + situationalMod;
  const defenseToken = h0dTargets.length === 1 ? h0dTargets[0] : null;
  const targetDefenseBase = defenseToken?.actor ? h0dResolveDefense(defenseToken.actor) : null;
  const weaponArmor = Math.max(0, Number(wp.H0D_Arme_Trait_AntiBlindage_Total || 0));
  const armorIgnore = Math.max(0, weaponArmor + ammoArmor);
  const targetDefense = targetDefenseBase === null ? null : Math.max(0, targetDefenseBase - armorIgnore);
  const attackVerdict = h0dAttackVerdict(natural, attackTotal, targetDefense);
  const publicMarginText = "";
  const defenseRow = "";
  if (targetDefense !== null) {
    try {
      const gmIds = ChatMessage.getWhisperRecipients("GM").map(u => u.id);
      if (gmIds.length) {
        const gmMargin = attackVerdict.margin === null ? "—" : ((attackVerdict.margin >= 0 ? "+" : "") + attackVerdict.margin);
        await ChatMessage.create({
