    : "";

  const damageFormula = baseDamage + " + (" + (damageFlat + ammoDmg) + ")";
  const damageRoll = await (new foundry.dice.Roll(damageFormula)).evaluate();
  const normalDamage = Number(damageRoll.total || 0);

  const threat = natural >= critThreshold && natural !== 1 && (targetDefense === null || attackVerdict.hit === true);
  let confirmNatural = null;
  let confirmTotal = null;
  let critDamage = null;
  let critConfirmed = null;
  const critParts = [];

  if (threat) {
    const confirmation = await (new foundry.dice.Roll("1d20")).evaluate();
    confirmNatural = Number(confirmation.total || 0);
    confirmTotal = confirmNatural + attackMod + ammoAtk + rangePenalty + situationalMod;
