    }

    try {
      await confirmation.toMessage({
        flavor: weapon.name + " — Confirmation de critique"
      });
    } catch (confirmErr) {
      console.warn("H0D — impossible d'afficher séparément le jet de confirmation", confirmErr);
    }

    critDamage = normalDamage;
    critParts.push(normalDamage);

    for (let i = 1; i < critMult; i++) {
      const extra = await (new foundry.dice.Roll(damageFormula)).evaluate();
      const v = Number(extra.total || 0);
      critDamage += v;
      critParts.push(v);
    }
  }

  if (mode === "Direct" && ammoItem) {
    const stock = Math.max(0, Number(ammoItem.system.props.H0D_Objet_Quantite || 0));
    await ammoItem.update({
      "system.props.H0D_Objet_Quantite": Math.max(0, stock - cost),
      "system.props.H0D_Objet_Munition_Active": true
    });
  }

  if (mode === "Chargeur") {
    const cur = Math.max(0, Number(wp.H0D_Arme_Munitions || 0));
    const next = Math.max(0, cur - cost);
    await weapon.update({"system.props.H0D_Arme_Munitions": next});
    if (next === 0) await weapon.unsetFlag("custom-system-builder", "h0dAmmoLoaded");
  }


  let cooldownAfterText = "";
  if (cdDuration > 0) {
    const liveCombat = game.combat || null;
    const liveRound = Number(liveCombat?.round || 0);

    if (cdMode === "Auto" && liveCombat && liveRound > 0) {
      await weapon.setFlag("custom-system-builder", "h0dCooldown", {
        mode:"Auto", active:true, combatId:String(liveCombat.id || ""), startRound:liveRound, elapsed:0
      });
      cooldownAfterText = "AUTO — 0/" + cdDuration + " (prêt au round " + (liveRound + cdDuration) + ")";
    } else {
      cdMode = "Manuel";
      await weapon.setFlag("custom-system-builder", "h0dCooldown", {
        mode:"Manuel", active:true, combatId:"", startRound:0, elapsed:0
      });
      cooldownAfterText = "MANUEL — 0/" + cdDuration;
    }
  }

  let threatText = critThreshold + "–20/x" + critMult;
  let critRows = "";

  if (threat) {
    if (targetDefense !== null) {
      if (attackVerdict.hit !== true) {
        threatText = "<strong>MENACE NON VALIDE</strong> — attaque initiale ratée";
      } else if (critConfirmed === true) {
        threatText = "<strong>CRITIQUE CONFIRMÉ</strong> (" + critThreshold + "–20/x" + critMult + ")";
      } else {
        threatText = "<strong>MENACE NON CONFIRMÉE</strong> (" + critThreshold + "–20/x" + critMult + ")";
      }
    } else {
      threatText = "<strong>MENACE DE CRITIQUE</strong> (" + critThreshold + "–20/x" + critMult + ")";
    }

    const confirmVerdictText = targetDefense === null
      ? "À comparer à la DEF"
      : (attackVerdict.hit !== true ? "Non applicable : attaque initiale ratée" : (critConfirmed ? "CONFIRMÉ" : "NON CONFIRMÉ"));

    critRows =
      "<tr><td>Confirmation</td><td>d20 <strong>" + confirmNatural + "</strong> + bonus "
      + (attackMod + ammoAtk + rangePenalty + situationalMod) + " = <strong>" + confirmTotal + "</strong></td></tr>"
      + "<tr><td>Confirmation vs DEF</td><td><strong>" + confirmVerdictText + "</strong></td></tr>"
      + "<tr><td>Dégâts critique</td><td><strong>" + critDamage + "</strong> (" + critParts.join(" + ") + ")</td></tr>";
  }

  let ammoRows = "";
  if (mode !== "Aucune") {
    ammoRows =
      "<tr><td>Munition</td><td><strong>" + esc(ammoName) + "</strong> — "
      + esc(afterAmmoText) + "</td></tr>"
      + "<tr><td>Élément</td><td>" + esc(ammoElement) + "</td></tr>";

    if (ammoArmor) {
      ammoRows += "<tr><td>Anti-blindage</td><td>" + ammoArmor + "</td></tr>";
    }
    if (ammoEffect) {
      ammoRows += "<tr><td>Effet munition</td><td>" + esc(ammoEffect) + "</td></tr>";
    }
  }

  const typeMain = String(wp.H0D_Arme_Type_Degats || "—");
  const range = isRangedAttack ? String(rangeIncrement) : String(wp.H0D_Arme_Portee || "—");
  const otherAttackMod = attackMod - bbaMod - abilityAttackMod - sizeAttackMod;
  const abilityName = category === "melee" ? "FOR" : (category === "distance" ? "DEX" : String(wp.H0D_Arme_Carac_Attaque || "—"));

  let rangeRows = "";
  if (isRangedAttack && measuredDistance !== null) {
    const distText = measuredDistance.toFixed(1) + (rangeUnits ? " " + rangeUnits : "");
    const incText = String(rangeIncrement) + (rangeUnits ? " " + rangeUnits : "");
    rangeRows =
      "<tr><td>Distance</td><td>" + esc(distText) + "</td></tr>"
      + "<tr><td>Intervalle</td><td>" + rangeBand + "/" + maxRangeBands
      + " · portée " + esc(incText) + "</td></tr>"
      + "<tr><td>Malus de portée</td><td><strong>"
      + (rangePenalty >= 0 ? "+" : "") + rangePenalty + "</strong></td></tr>";
  }

    function h0dSign(v) {
    const n = Number(v) || 0;
    return (n >= 0 ? "+" : "") + n;
  }
  function h0dDetailRow(label, value, strong=false) {
    return "<tr><td>" + esc(label) + "</td><td style=\"text-align:right;\">"
      + (strong ? "<strong>" : "") + esc(value) + (strong ? "</strong>" : "") + "</td></tr>";
  }

  // Décomposer uniquement les modificateurs qui ont réellement participé au jet.
  const weaponAttackBonus = Number(wp.H0D_Arme_Bonus_Attaque || 0);
  const weaponTraitAttackBonus = Number(wp.H0D_Arme_Trait_Attaque_Total || 0);
  const equipmentAttackBonus = Number("${H0D_EQ_Trait_Attaque_Global_Total}$") || 0;
  const encumbranceAttackBonus = Number("${H0D_Encombrement_Malus_Calc}$") || 0;
  const featGlobalAttackBonus = Number("${H0D_DT_Bonus_Attaque_Global_Total}$") || 0;
  const featCategoryAttackBonus = Number("${switchCase(item.H0D_Arme_Categorie,'distance',H0D_DT_Bonus_Attaque_Distance_Total,'jet',H0D_DT_Bonus_Attaque_Distance_Total,'melee',H0D_DT_Bonus_Attaque_Melee_Total,0)}$") || 0;
  const heavyAttackBonus = Number("${item.H0D_Arme_Trait_Lourd_FOR_Min_Calc > H0D_FOR ? -2 : 0}$") || 0;
  const identifiedAttackBonus = bbaMod + abilityAttackMod + sizeAttackMod + weaponAttackBonus
    + weaponTraitAttackBonus + equipmentAttackBonus + encumbranceAttackBonus
    + featGlobalAttackBonus + featCategoryAttackBonus + heavyAttackBonus;
  const residualAttackBonus = attackMod - identifiedAttackBonus;
  const totalAttackBonus = attackTotal - natural;

  let compactDetails = "";
  compactDetails += h0dDetailRow("d20", natural, true);
  compactDetails += h0dDetailRow("BBA", h0dSign(bbaMod));
  compactDetails += h0dDetailRow(abilityName, h0dSign(abilityAttackMod));
  if (sizeAttackMod !== 0) compactDetails += h0dDetailRow("Taille", h0dSign(sizeAttackMod));
  if (weaponAttackBonus !== 0) compactDetails += h0dDetailRow("Arme", h0dSign(weaponAttackBonus));
  if (weaponTraitAttackBonus !== 0) compactDetails += h0dDetailRow("Trait d’arme", h0dSign(weaponTraitAttackBonus));
  if (equipmentAttackBonus !== 0) compactDetails += h0dDetailRow("Équipement", h0dSign(equipmentAttackBonus));
  if (featGlobalAttackBonus !== 0) compactDetails += h0dDetailRow("Dons / talents", h0dSign(featGlobalAttackBonus));
  if (featCategoryAttackBonus !== 0) compactDetails += h0dDetailRow("Dons — catégorie", h0dSign(featCategoryAttackBonus));
  if (encumbranceAttackBonus !== 0) compactDetails += h0dDetailRow("Encombrement", h0dSign(encumbranceAttackBonus));
  if (heavyAttackBonus !== 0) compactDetails += h0dDetailRow("Arme lourde", h0dSign(heavyAttackBonus));
  if (residualAttackBonus !== 0) compactDetails += h0dDetailRow("Autre", h0dSign(residualAttackBonus));
  if (ammoAtk !== 0) compactDetails += h0dDetailRow("Munition", h0dSign(ammoAtk));
  if (rangePenalty !== 0) {
    const rangeContext = measuredDistance !== null
      ? (measuredDistance.toFixed(1) + (rangeUnits ? " " + rangeUnits : "") + " · " + h0dSign(rangePenalty))
      : h0dSign(rangePenalty);
    compactDetails += h0dDetailRow("Portée", rangeContext);
  }
  if (situationalMod !== 0) compactDetails += h0dDetailRow("Situationnel", h0dSign(situationalMod));
  if (armorIgnore > 0) compactDetails += h0dDetailRow("Anti-blindage", "DEF -" + armorIgnore);
  compactDetails += h0dDetailRow("Bonus total", h0dSign(totalAttackBonus), true);

  let compactMeta = "";
  if (mode !== "Aucune" && ammoName && ammoName !== "—") {
    compactMeta += "<span>Munition : <b>" + esc(ammoName) + "</b> · " + esc(afterAmmoText) + "</span>";
  }
  if (mode !== "Aucune" && ammoElement && ammoElement !== "Aucun" && ammoElement !== "—") {
    compactMeta += "<span>Élément : <b>" + esc(ammoElement) + "</b></span>";
  }
  if (cooldownAfterText) compactMeta += "<span>Recharge : <b>" + esc(cooldownAfterText) + "</b></span>";

  const h0dEffectText = String(wp.H0D_Arme_Effet_Special || "").trim();
  const h0dEffectRow = h0dEffectText
    ? "<tr><td>Effet</td><td><strong>" + esc(h0dEffectText) + "</strong></td></tr>"
    : "";

  let compactCritRows = "";
  if (threat) {
    compactCritRows += "<tr><td>Critique</td><td style=\"text-align:right;\">" + threatText + "</td></tr>";
    if (critDamage !== null && (critConfirmed === true || targetDefense === null)) {
      compactCritRows += "<tr><td>Dégâts critique</td><td style=\"text-align:right;\"><strong>" + critDamage + "</strong></td></tr>";
    }
  }

  return "<div class=\"h0d-chat-card h0d-chat-attack h0d-chat-pj\">"
    + "<div class=\"h0d-chat-headline\">" + esc(weapon.name) + "</div>"
    + warningBox
    + "<table class=\"h0d-chat-summary\">"
    + "<tr><td><strong>Résultat</strong></td><td><strong>" + attackTotal + "</strong></td></tr>"
    + "<tr><td><strong>Verdict</strong></td><td><strong>" + attackVerdict.text + publicMarginText + "</strong></td></tr>"
    + "<tr><td>Cible</td><td><strong>" + esc(targetName) + "</strong></td></tr>"
    + defenseRow
    + "<tr><td>Dégâts</td><td><strong>" + normalDamage + "</strong></td></tr>"
    + compactCritRows
    + h0dEffectRow
    + "</table>"
    + (compactMeta ? "<div class=\"h0d-chat-meta\">" + compactMeta + "</div>" : "")
    + "<details><summary>Détails du jet</summary><table>" + compactDetails + "</table></details>"
    + "</div>";

} catch (err) {
  console.error("H0D — erreur jet attaque", err);
  const message = "Jet d'attaque H0D : " + (err && err.message ? err.message : String(err));
  if (ui.notifications) ui.notifications.error(message);
  return "<strong>ERREUR JET D'ATTAQUE</strong><br>"
    + (err && err.message ? err.message : String(err));
}
}%

%{
const actor = entity.entity ? entity.entity : entity;
const weapon = linkedEntity;
if (!weapon) return "<strong>Arme introuvable.</strong>";

const wp = weapon.system && weapon.system.props ? weapon.system.props : {};
const category = String(wp.H0D_Arme_Categorie || "");
const mode = category === "melee" ? "Aucune" : String(wp.H0D_Arme_Mode_Munition || "Aucune");
const family = String(wp.H0D_Arme_Type_Munition || "");
const items = actor.items ? actor.items : entity.items;

function ammoCandidates() {
  return items.filter(function(i) {
    const p = i.system && i.system.props ? i.system.props : {};
    return String(p.H0D_Objet_Type || "") === "Munition"
      && String(p.H0D_Stockage || "PJ") === "PJ"
      && String(p.H0D_Objet_Munition_Famille || "") === family
      && Number(p.H0D_Objet_Quantite || 0) > 0;
  });
}

function chosenAmmo() {
  const candidates = ammoCandidates();
  let selected = candidates.find(function(i) {
    const p = i.system && i.system.props ? i.system.props : {};
    return p.H0D_Objet_Munition_Active === true || p.H0D_Objet_Munition_Active === "true";
  });
  if (!selected && candidates.length === 1) selected = candidates[0];
  return {selected: selected, candidates: candidates};
}

if (mode === "Aucune") {
  return "<strong>" + weapon.name + "</strong> n'utilise pas de munitions.";
}

if (mode === "Direct") {
  const result = chosenAmmo();
  if (!result.selected) {
    if (result.candidates.length > 1) {
      return "<strong>" + weapon.name + "</strong> : plusieurs munitions compatibles. Sélectionnez-en une dans MUNITIONS.";
    }
    return "<strong>" + weapon.name + "</strong> : aucune munition " + family + " disponible.";
  }
  const q = Number(result.selected.system.props.H0D_Objet_Quantite || 0);
  return "<strong>" + weapon.name + "</strong> — munition directe : <strong>"
    + result.selected.name + "</strong> (" + q + " restante" + (q > 1 ? "s" : "") + ").";
}

const max = Math.max(0, Number(wp.H0D_Arme_Munitions_Max || 0));
const cur = Math.max(0, Number(wp.H0D_Arme_Munitions || 0));

if (max <= 0) return "<strong>" + weapon.name + "</strong> : capacité de chargeur non définie.";
if (cur >= max) return "<strong>" + weapon.name + "</strong> : chargeur déjà plein (" + cur + "/" + max + ").";

const result = chosenAmmo();
if (!result.selected) {
  if (result.candidates.length > 1) {
    return "<strong>" + weapon.name + "</strong> : plusieurs munitions " + family + " compatibles. Sélectionnez-en une avant de recharger.";
  }
  return "<strong>" + weapon.name + "</strong> : aucune munition " + family + " disponible pour recharger.";
}

const loadedAmmo = weapon.getFlag("custom-system-builder", "h0dAmmoLoaded") || {};
const loadedId = String(loadedAmmo.id || "");
if (cur > 0 && loadedId && loadedId !== result.selected.id) {
  const loadedName = String(loadedAmmo.name || "munition différente");
  return "<strong>" + weapon.name + "</strong> contient déjà " + cur + " × " + loadedName
    + ". Terminez ou videz le chargeur avant de changer de munition.";
}

const ap = result.selected.system && result.selected.system.props ? result.selected.system.props : {};
const stock = Math.max(0, Number(ap.H0D_Objet_Quantite || 0));
const need = max - cur;
const moved = Math.min(need, stock);

if (moved <= 0) return "<strong>" + result.selected.name + "</strong> : stock épuisé.";

await result.selected.update({
  "system.props.H0D_Objet_Quantite": stock - moved,
  "system.props.H0D_Objet_Munition_Active": true
});

await weapon.update({"system.props.H0D_Arme_Munitions": cur + moved});
await weapon.setFlag("custom-system-builder", "h0dAmmoLoaded", {
  id: result.selected.id,
  name: result.selected.name,
  element: String(ap.H0D_Objet_Munition_Element || "Aucun"),
  attackBonus: Number(ap.H0D_Objet_Munition_Bonus_Attaque || 0),
  damageBonus: Number(ap.H0D_Objet_Munition_Bonus_Degats || 0),
  antiArmor: Number(ap.H0D_Objet_Munition_Anti_Blindage || 0),
  effect: String(ap.H0D_Objet_Munition_Effet_Court || "")
});

return "<strong>" + weapon.name + "</strong> rechargée : +" + moved + " × " + result.selected.name
  + " (" + (cur + moved) + "/" + max + "). Stock restant : " + (stock - moved) + ".";
}%

%{
const weapon = linkedEntity;
if (!weapon) return "<strong>Arme introuvable.</strong>";

const p = weapon.system && weapon.system.props ? weapon.system.props : {};
const duration = Math.max(0, Number(p.H0D_Arme_Trait_Cooldown_Total || 0));
if (duration <= 0) return "<strong>" + weapon.name + "</strong> : aucun cooldown.";

let state = weapon.getFlag("custom-system-builder", "h0dCooldown") || {};
let mode = String(state.mode || "Auto");
let active = state.active === true;
let elapsed = Math.max(0, Number(state.elapsed || 0));
const combat = game.combat || null;
const round = Number(combat?.round || 0);

if (active && mode === "Auto") {
  const sameCombat = combat && round > 0
    && String(state.combatId || "") === String(combat.id || "")
    && Number(state.startRound || 0) > 0;
  if (sameCombat) {
    elapsed = Math.max(0, round - Number(state.startRound || 0));
    if (elapsed >= duration) active = false;
  } else {
    active = false;
    elapsed = duration;
  }
}

const selectedAuto = mode === "Manuel" ? "" : " selected";
const selectedManual = mode === "Manuel" ? " selected" : "";
const selectedActive = active ? " selected" : "";
const selectedReady = active ? "" : " selected";

const fd = await foundry.applications.api.DialogV2.input({
  window: {title: "Cooldown — " + weapon.name},
  content:
    "<div class=\"form-group\"><label>Mode</label>"
    + "<select name=\"mode\">"
    + "<option value=\"Auto\"" + selectedAuto + ">Automatique — Combat Tracker</option>"
    + "<option value=\"Manuel\"" + selectedManual + ">Manuel</option>"
    + "</select></div>"
    + "<div class=\"form-group\"><label>État</label>"
    + "<select name=\"state\">"
    + "<option value=\"active\"" + selectedActive + ">En recharge</option>"
    + "<option value=\"ready\"" + selectedReady + ">Prêt</option>"
    + "</select></div>"
    + "<div class=\"form-group\"><label>Rounds écoulés</label>"
    + "<input name=\"elapsed\" type=\"number\" min=\"0\" max=\"" + duration
    + "\" step=\"1\" value=\"" + Math.min(duration, elapsed) + "\"></div>"
    + "<p><strong>Durée :</strong> " + duration + " round(s).</p>",
  ok: {label: "Appliquer"}, rejectClose: false, modal: true
});

if (!fd) return "<strong>" + weapon.name + "</strong> : cooldown inchangé.";

let newMode = String(fd.mode || mode);
let newActive = String(fd.state || "ready") === "active";
let newElapsed = Math.max(0, Math.min(duration, Number(fd.elapsed || 0)));
if (newElapsed >= duration) newActive = false;

let newState = {mode:newMode, active:newActive, elapsed:newActive ? newElapsed : duration, combatId:"", startRound:0};
if (newMode === "Auto" && newActive) {
  if (combat && round > 0) {
    newState.combatId = String(combat.id || "");
    newState.startRound = Math.max(1, round - newElapsed);
  } else {
    newMode = "Manuel";
    newState.mode = "Manuel";
    if (ui.notifications) ui.notifications.warn("H0D : aucun combat actif, passage du cooldown en mode manuel.");
  }
}

await weapon.setFlag("custom-system-builder", "h0dCooldown", newState);
return "<strong>" + weapon.name + "</strong><br>"
  + "Mode : " + newMode + "<br>"
  + "État : " + (newActive ? "en recharge" : "prêt") + "<br>"
  + "Rounds écoulés : " + (newActive ? newElapsed : duration) + " / " + duration + ".";
}%

