contents.rollMessage:
%{
const cls = "${H0D_Classe_Prochain_Niveau}$";
const die = cls === "Robuste" ? "1d10" : (cls === "Fort" || cls === "Rapide" ? "1d8" : "1d6");
const roll = await (new foundry.dice.Roll(die)).evaluate();
const con = Number("${H0D_CON_MOD}$") || 0;
const gain = Math.max(1, Number(roll.total) + con);
return "<div class=\"h0d-chat-card h0d-chat-progression h0d-chat-pj\">"
 + "<div class=\"h0d-chat-headline\">Dé de vie — prochain niveau</div>"
 + "<table class=\"h0d-chat-summary\"><tr><td><strong>Gain de PV</strong></td><td><strong>+" + gain + "</strong></td></tr></table>"
 + "<details><summary>Détails du jet</summary><table>"
 + "<tr><td>Classe</td><td>" + cls + "</td></tr>"
 + "<tr><td>Dé</td><td>" + die.replace("1d","d") + "</td></tr>"
 + "<tr><td>Résultat brut</td><td>" + roll.total + "</td></tr>"
 + "<tr><td>CON</td><td>" + (con >= 0 ? "+" : "") + con + "</td></tr>"
 + "<tr><td>Minimum</td><td>1 PV</td></tr>"
 + "</table></details>"
 + "</div>";
}%

