%{
const actor = entity.entity ? entity.entity : entity;
const ammo = linkedEntity;
if (!ammo) return "<strong>Munition introuvable.</strong>";

const props = ammo.system && ammo.system.props ? ammo.system.props : {};
const family = String(props.H0D_Objet_Munition_Famille || "");
const nowActive = props.H0D_Objet_Munition_Active === true || props.H0D_Objet_Munition_Active === "true";

if (nowActive) {
  await ammo.update({"system.props.H0D_Objet_Munition_Active": false});
  return "<strong>" + ammo.name + "</strong> : désélectionnée.";
}

const items = actor.items ? actor.items : entity.items;
for (const other of items) {
  if (other.id === ammo.id) continue;
  const op = other.system && other.system.props ? other.system.props : {};
  const isAmmo = String(op.H0D_Objet_Type || "") === "Munition";
  const sameFamily = String(op.H0D_Objet_Munition_Famille || "") === family;
  const active = op.H0D_Objet_Munition_Active === true || op.H0D_Objet_Munition_Active === "true";
  if (isAmmo && sameFamily && active) {
    await other.update({"system.props.H0D_Objet_Munition_Active": false});
  }
}

await ammo.update({"system.props.H0D_Objet_Munition_Active": true});
return "<strong>" + ammo.name + "</strong> sélectionnée pour la famille <strong>" + family + "</strong>.";
}%

